import{o as n,c as s,a0 as i,j as o,t as r,p as d}from"./chunks/framework.L_oL6aia.js";const c={class:"rock-card-contact",style:{"max-width":"600px",margin:"3rem auto 1rem auto"}},l={class:"rock-copy-email-wrapper card-contact"},m=JSON.parse('{"title":"Beast of Burden: User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"beast-of-burden.md","filePath":"beast-of-burden.md"}'),u={name:"beast-of-burden.md"},b=Object.assign(u,{setup(g){const t=d("Copy Email");function a(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),t.value="Copied!",setTimeout(function(){t.value="Copy Email"},2e3)}return(h,e)=>(n(),s("div",null,[e[3]||(e[3]=i(`<h1 id="beast-of-burden-user-manual" tabindex="-1">Beast of Burden: User Manual <a class="header-anchor" href="#beast-of-burden-user-manual" aria-label="Permalink to &quot;Beast of Burden: User Manual&quot;">​</a></h1><p><strong>Version 1.0.0 · Virtual Stompbox &amp; Amplifier Simulation</strong></p><p>This manual provides a detailed description of the design philosophy, signal chain architecture, control parameters, and recommended presets for the <strong>Beast of Burden</strong> amplifier emulation and vintage FX suite.</p><img src="/bob.png" alt="Beast of Burden Plugin GUI" style="max-height:280px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:4px;"><hr><h2 id="_1-design-philosophy-the-1978-king-of-crunch-stones-mojo" tabindex="-1">1. Design Philosophy: The 1978 King of Crunch &amp; Stones Mojo <a class="header-anchor" href="#_1-design-philosophy-the-1978-king-of-crunch-stones-mojo" aria-label="Permalink to &quot;1. Design Philosophy: The 1978 King of Crunch &amp; Stones Mojo&quot;">​</a></h2><p><strong>Beast of Burden</strong> is a dual-engine audio processor pairing an authentic emulation of the legendary <strong>1977–1978 Mesa/Boogie Mark I (100W 6L6 with Electro-Voice EVM-12L speaker)</strong> with the signature <strong>Stones &#39;78 Vintage Dual FX Suite</strong> (Phase &#39;78 optical phaser and analog tape slapback delay).</p><h3 id="the-sound-of-some-girls-1978" tabindex="-1">The Sound of <em>Some Girls</em> (1978) <a class="header-anchor" href="#the-sound-of-some-girls-1978" aria-label="Permalink to &quot;The Sound of *Some Girls* (1978)&quot;">​</a></h3><p>In late 1977, during the legendary Paris sessions at Pathé Marconi Studios and the explosive 1978 US Tour, Keith Richards and Ron Wood armed themselves with custom Mesa/Boogie Mark I 100W combos. Moving away from the dense low-mid wall of the early &#39;70s, the Mark I brought:</p><ul><li><strong>Hyper-Fast Attack &amp; Punch:</strong> Driven by massive transformers, four 6L6 power tubes, and the ultra-efficient 200W Electro-Voice EVM-12L speaker.</li><li><strong>Liquid Modulation &amp; Dimension:</strong> Running the guitars through an MXR Phase 100 pedal and short tape slapback echo before hitting the cascaded tube preamps.</li><li><strong>The Iconic 5-Band Graphic EQ &quot;V-Curve&quot;:</strong> Sculpting the aggressive upper-mid bite (2.2 kHz) and vocal presence (750 Hz) while cleaning up low-mid mud (240 Hz).</li></ul><h3 id="neural-amp-modeler-nam-engine" tabindex="-1">Neural Amp Modeler (NAM) Engine <a class="header-anchor" href="#neural-amp-modeler-nam-engine" aria-label="Permalink to &quot;Neural Amp Modeler (NAM) Engine&quot;">​</a></h3><p>Powered by deep WaveNet neural networks compiled with full AVX/SIMD vectorization, Beast of Burden reproduces every non-linear nuance of tube sag, harmonic saturation, dynamic compression, and touch response with <strong>ultra-low latency (&lt;0.2 ms per block)</strong> and minimal CPU consumption.</p><hr><h2 id="_2-neural-amp-architecture-3-channel-matrix" tabindex="-1">2. Neural Amp Architecture &amp; 3-Channel Matrix <a class="header-anchor" href="#_2-neural-amp-architecture-3-channel-matrix" aria-label="Permalink to &quot;2. Neural Amp Architecture &amp; 3-Channel Matrix&quot;">​</a></h2><p>Beast of Burden features a flexible 3-channel matrix with an independent <strong>BRIGHT</strong> switch, covering the full sonic spectrum from pristine vintage Tweed cleans to roaring high-gain lead sustain:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Channel Mode</th><th style="text-align:left;">Preamp Configuration</th><th style="text-align:left;">Tone Profile &amp; Applications</th><th style="text-align:center;">Perceived Gain Leveling</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>IN 2 (Rhythm)</code></strong></td><td style="text-align:left;">Single-stage Tweed / Blackface clean preamp</td><td style="text-align:left;">Broad dynamic headroom, sparkling top end, and transparent touch response. The ultimate choice for open-G chord work, funk chops, and dynamic rhythm playing.</td><td style="text-align:center;"><strong>+14.5 dB</strong> (Post-Amp Leveling)</td></tr><tr><td style="text-align:left;"><strong><code>IN 1 (Crunch - Vol 5)</code></strong></td><td style="text-align:left;">Cascaded dual-triode preamp (Volume 1 @ 5)</td><td style="text-align:left;">Organic edge-of-breakup into dynamic crunch. Responds dynamically to pick attack: cleans up with a light touch and growls when digging in.</td><td style="text-align:center;"><strong>+4.5 dB</strong> (Post-Amp Leveling)</td></tr><tr><td style="text-align:left;"><strong><code>IN 1 (Lead 10)</code></strong></td><td style="text-align:left;">Cascaded dual-triode preamp (Volume 1 @ 10)</td><td style="text-align:left;">Searing full tube saturation, dense harmonic compression, singing sustain, and smoothed top end. Perfect for screaming solos, slide, and taming bright single-coil guitars.</td><td style="text-align:center;"><strong>0.0 dB</strong> (Nominal RMS)</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Intelligent Perceived Loudness Leveling:</strong> Because uncompressed clean channels naturally have lower RMS volume than heavily clipped lead channels, Beast of Burden automatically levels the post-amp output stage. Switching between <code>IN 2</code>, <code>IN 1 Crunch</code>, and <code>Lead 10</code> maintains consistent perceived volume across your mix.</p></div><hr><h2 id="_3-complete-control-guide" tabindex="-1">3. Complete Control Guide <a class="header-anchor" href="#_3-complete-control-guide" aria-label="Permalink to &quot;3. Complete Control Guide&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ INPUT SIGNAL ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ PHASE &#39;78 ]  ───►  [ SLAPBACK DELAY ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ INPUT GAIN ] ───►  [ NAM 100W 6L6 TUBE ENGINE ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ TONE STACK ] ───►  [ 5-BAND GRAPHIC EQ ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ EVM-12L IR CONVOLVER ]  ───►  [ MASTER OUTPUT GAIN ]  ───►  [ STEREO OUT ]</span></span></code></pre></div><h3 id="🎛️-1-main-amplifier-controls" tabindex="-1">🎛️ 1. Main Amplifier Controls <a class="header-anchor" href="#🎛️-1-main-amplifier-controls" aria-label="Permalink to &quot;🎛️ 1. Main Amplifier Controls&quot;">​</a></h3><ul><li><strong><code>GAIN</code> (Volume / Drive):</strong> Sets input signal drive into the neural engine (<code>1.0</code> = -18 dB clean to <code>10.0</code> = 0 dB unattenuated).</li><li><strong><code>TREBLE</code>:</strong> Passive high-frequency tone control (<code>4 kHz</code> to <code>20 kHz</code>).</li><li><strong><code>BASS</code>:</strong> Passive low-frequency tone control (<code>20 Hz</code> to <code>120 Hz</code>). Keep at lower settings (<code>3.0 – 4.5</code>) to keep 100W 6L6 low-end tight and punchy.</li><li><strong><code>MIDDLE</code>:</strong> Passive midrange tone control shaping body and vocal roar.</li><li><strong><code>PRESENCE</code>:</strong> Active power-amp feedback control adding top-end sparkle and bite.</li><li><strong><code>MASTER</code>:</strong> Linear analog output volume (<code>1.0</code> = -36 dB bedroom volume, <code>7.0</code> = 0 dB Unity Gain, <code>10.0</code> = +18 dB boost).</li><li><strong><code>BRIGHT SWITCH</code>:</strong> Adds a high-frequency shelf bypass across the volume pot, delivering extra chime and clarity for humbucker neck pickups.</li><li><strong><code>CHANNEL MODE</code>:</strong> 3-position rotary selector switching between <code>IN 2 (Rhythm)</code>, <code>IN 1 (Crunch)</code>, and <code>IN 1 (Lead 10)</code>.</li></ul><hr><h3 id="🎚️-2-5-band-graphic-equalizer" tabindex="-1">🎚️ 2. 5-Band Graphic Equalizer <a class="header-anchor" href="#🎚️-2-5-band-graphic-equalizer" aria-label="Permalink to &quot;🎚️ 2. 5-Band Graphic Equalizer&quot;">​</a></h3><p>An authentic recreation of the classic Mesa/Boogie active slider EQ with an independent <strong><code>EQ IN</code></strong> toggle and status LED:</p><ul><li><strong><code>80 Hz</code> (±12 dB):</strong> Controls deep sub-bass thump. Keep between <code>0 dB</code> and <code>+2 dB</code> for tight, focused low end.</li><li><strong><code>240 Hz</code> (±12 dB):</strong> Controls low-mid boxiness. Cutting <code>-2 dB</code> to <code>-4 dB</code> instantly clears mud and opens up clarity.</li><li><strong><code>750 Hz</code> (±12 dB):</strong> Midrange punch. Boosting <code>+2 dB</code> to <code>+4 dB</code> brings out the signature Stones guitar bark.</li><li><strong><code>2200 Hz / 2.2 kHz</code> (±12 dB):</strong> The attack frequency! Boosting <code>+3 dB</code> to <code>+5 dB</code> delivers the unmistakable pick snap of <em>Beast of Burden</em> and <em>Start Me Up</em>.</li><li><strong><code>6600 Hz / 6.6 kHz</code> (±12 dB):</strong> Smooth air and chime characteristic of the Electro-Voice EVM-12L speaker.</li></ul><hr><h3 id="🌀-3-stones-78-vintage-dual-fx-suite" tabindex="-1">🌀 3. Stones &#39;78 Vintage Dual FX Suite <a class="header-anchor" href="#🌀-3-stones-78-vintage-dual-fx-suite" aria-label="Permalink to &quot;🌀 3. Stones &#39;78 Vintage Dual FX Suite&quot;">​</a></h3><p>Integrated directly before the preamp stage, replicating the exact pedalboard signal flow used on classic records:</p><h4 id="phase-78-mxr-phase-100-style-optical-phaser" tabindex="-1"><strong>Phase &#39;78 (MXR Phase 100 Style Optical Phaser)</strong> <a class="header-anchor" href="#phase-78-mxr-phase-100-style-optical-phaser" aria-label="Permalink to &quot;**Phase &#39;78 (MXR Phase 100 Style Optical Phaser)**&quot;">​</a></h4><ul><li><strong><code>PHASE &#39;78 Toggle &amp; Amber LED</code>:</strong> Activates or bypasses the phaser.</li><li><strong><code>SPEED</code> (<code>0.1 Hz</code> to <code>5.0 Hz</code>):</strong> Controls the LFO modulation rate. Displayed dynamically in real time.</li><li><strong><code>INTENS</code> (<code>0%</code> to <code>100%</code>):</strong> Controls sweep depth and vocal resonance.</li></ul><h4 id="slapback-delay-analog-tape-echo" tabindex="-1"><strong>Slapback Delay (Analog Tape Echo)</strong> <a class="header-anchor" href="#slapback-delay-analog-tape-echo" aria-label="Permalink to &quot;**Slapback Delay (Analog Tape Echo)**&quot;">​</a></h4><ul><li><strong><code>SLAPBACK Toggle &amp; Red LED</code>:</strong> Activates or bypasses the tape echo.</li><li><strong><code>TIME</code> (<code>20 ms</code> to <code>400 ms</code>):</strong> Sets delay time with dynamic millisecond readout. Default: <code>110 ms</code> (the classic slapback sweet spot).</li><li><strong><code>REPEATS</code> (<code>0%</code> to <code>80%</code>):</strong> Controls tape feedback. Set to <code>15% – 20%</code> for a single clean bounce.</li><li><strong><code>MIX</code> (<code>0%</code> to <code>100%</code>):</strong> Controls wet/dry balance.</li></ul><hr><h3 id="🔊-4-electro-voice-evm-12l-cabinet-convolution" tabindex="-1">🔊 4. Electro-Voice EVM-12L Cabinet Convolution <a class="header-anchor" href="#🔊-4-electro-voice-evm-12l-cabinet-convolution" aria-label="Permalink to &quot;🔊 4. Electro-Voice EVM-12L Cabinet Convolution&quot;">​</a></h3><p>The Electro-Voice EVM-12L 200W speaker is renowned for its neutral response, massive power handling, and punchy definition. The <strong><code>CABINET</code></strong> selector provides 5 studio-captured impulse responses plus a bypass mode:</p><ol><li><strong><code>441 Center</code>:</strong> Sennheiser MD441 dynamic mic on center cap — tight, bright, and aggressive.</li><li><strong><code>441 Edge</code>:</strong> Sennheiser MD441 on cone edge — warm, smooth, and balanced.</li><li><strong><code>4050 On-Ax</code>:</strong> Audio-Technica AT4050 large condenser — full frequency spectrum with three-dimensional depth.</li><li><strong><code>4x12 Close</code>:</strong> 4x12 EVM-12L closed-back cab close mic&#39;d — massive punch and low-end impact.</li><li><strong><code>4x12 Big</code>:</strong> 4x12 EVM-12L cab with room air — spacious, expansive rock tone.</li><li><strong><code>Bypass IR</code>:</strong> Disables internal convolution for pairing with external third-party IR loaders.</li></ol><hr><h3 id="🖼️-5-standby-custom-tolex-skinning" tabindex="-1">🖼️ 5. Standby &amp; Custom Tolex Skinning <a class="header-anchor" href="#🖼️-5-standby-custom-tolex-skinning" aria-label="Permalink to &quot;🖼️ 5. Standby &amp; Custom Tolex Skinning&quot;">​</a></h3><ul><li><strong><code>STANDBY</code>:</strong> Mutes audio output and reduces neural CPU processing to <strong>0%</strong> immediately.</li><li><strong>Drag-and-Drop Backgrounds:</strong> Drag any <code>.jpg</code>, <code>.jpeg</code>, or <code>.png</code> image directly onto the plugin window from your file manager to customize its visual skin in real time.</li></ul><hr><h2 id="_4-recommended-track-presets-dial-in-guides" tabindex="-1">4. Recommended Track Presets &amp; Dial-In Guides <a class="header-anchor" href="#_4-recommended-track-presets-dial-in-guides" aria-label="Permalink to &quot;4. Recommended Track Presets &amp; Dial-In Guides&quot;">​</a></h2><p>Here are studio-tested dial-in settings for iconic Rolling Stones guitar tones:</p><h3 id="🌟-preset-1-beast-of-burden-the-signature-liquid-phase-tone" tabindex="-1">🌟 Preset 1: &quot;Beast of Burden&quot; (The Signature Liquid Phase Tone) <a class="header-anchor" href="#🌟-preset-1-beast-of-burden-the-signature-liquid-phase-tone" aria-label="Permalink to &quot;🌟 Preset 1: &quot;Beast of Burden&quot; (The Signature Liquid Phase Tone)&quot;">​</a></h3><ul><li><strong>Channel Mode:</strong> <code>IN 2 (Rhythm)</code></li><li><strong>Bright Switch:</strong> <code>ON</code></li><li><strong>Amp Tone Stack:</strong> Gain: <code>7.0</code> | Treble: <code>7.5</code> | Bass: <code>3.5</code> | Middle: <code>7.0</code> | Presence: <code>5.5</code> | Master: <code>7.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: 0dB</code> | <code>240Hz: -2.5dB</code> | <code>750Hz: +2.5dB</code> | <code>2.2kHz: +3.5dB</code> | <code>6.6kHz: +1.5dB</code></li><li><strong>Phase &#39;78:</strong> <code>ON</code> | Speed: <code>0.8 Hz</code> (9:30 o&#39;clock) | Intensity: <code>60%</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>110 ms</code> | Repeats: <code>18%</code> | Mix: <code>22%</code></li><li><strong>Cabinet:</strong> <code>441 Center</code></li></ul><h3 id="⚡-preset-2-shattered-new-york-disco-punk-crunch" tabindex="-1">⚡ Preset 2: &quot;Shattered&quot; (New York Disco-Punk Crunch) <a class="header-anchor" href="#⚡-preset-2-shattered-new-york-disco-punk-crunch" aria-label="Permalink to &quot;⚡ Preset 2: &quot;Shattered&quot; (New York Disco-Punk Crunch)&quot;">​</a></h3><ul><li><strong>Channel Mode:</strong> <code>IN 1 (Crunch)</code></li><li><strong>Bright Switch:</strong> <code>ON</code></li><li><strong>Amp Tone Stack:</strong> Gain: <code>6.5</code> | Treble: <code>8.0</code> | Bass: <code>3.0</code> | Middle: <code>7.5</code> | Presence: <code>6.5</code> | Master: <code>7.5</code></li><li><strong>Phase &#39;78:</strong> <code>ON</code> | Speed: <code>1.4 Hz</code> (11:00 o&#39;clock) | Intensity: <code>70%</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>95 ms</code> | Repeats: <code>25%</code> | Mix: <code>30%</code></li><li><strong>Cabinet:</strong> <code>4050 On-Ax</code></li></ul><h3 id="🕺-preset-3-miss-you-tight-funk-rock-chops" tabindex="-1">🕺 Preset 3: &quot;Miss You&quot; (Tight Funk-Rock Chops) <a class="header-anchor" href="#🕺-preset-3-miss-you-tight-funk-rock-chops" aria-label="Permalink to &quot;🕺 Preset 3: &quot;Miss You&quot; (Tight Funk-Rock Chops)&quot;">​</a></h3><ul><li><strong>Channel Mode:</strong> <code>IN 2 (Rhythm)</code></li><li><strong>Bright Switch:</strong> <code>OFF</code></li><li><strong>Amp Tone Stack:</strong> Gain: <code>5.5</code> | Treble: <code>7.0</code> | Bass: <code>4.0</code> | Middle: <code>6.5</code> | Presence: <code>5.0</code> | Master: <code>7.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: +1dB</code> | <code>240Hz: -3.0dB</code> | <code>750Hz: +1.5dB</code> | <code>2.2kHz: +4.0dB</code> | <code>6.6kHz: +1.0dB</code></li><li><strong>Phase &#39;78:</strong> <code>OFF</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>120 ms</code> | Repeats: <code>15%</code> | Mix: <code>18%</code></li><li><strong>Cabinet:</strong> <code>441 Edge</code></li></ul><h3 id="🎸-preset-4-start-me-up-the-definitive-open-g-riff-crunch" tabindex="-1">🎸 Preset 4: &quot;Start Me Up&quot; (The Definitive Open-G Riff Crunch) <a class="header-anchor" href="#🎸-preset-4-start-me-up-the-definitive-open-g-riff-crunch" aria-label="Permalink to &quot;🎸 Preset 4: &quot;Start Me Up&quot; (The Definitive Open-G Riff Crunch)&quot;">​</a></h3><ul><li><strong>Channel Mode:</strong> <code>IN 1 (Crunch)</code></li><li><strong>Bright Switch:</strong> <code>ON</code></li><li><strong>Amp Tone Stack:</strong> Gain: <code>7.5</code> | Treble: <code>7.5</code> | Bass: <code>3.0</code> | Middle: <code>8.0</code> | Presence: <code>6.0</code> | Master: <code>8.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: +1.5dB</code> | <code>240Hz: -3.5dB</code> | <code>750Hz: +3.0dB</code> | <code>2.2kHz: +4.5dB</code> | <code>6.6kHz: +2.0dB</code></li><li><strong>Phase &#39;78:</strong> <code>OFF</code></li><li><strong>Slapback Delay:</strong> <code>OFF</code> (or <code>ON</code> with Mix @ <code>12%</code> for studio space)</li><li><strong>Cabinet:</strong> <code>4x12 Close</code></li></ul><h3 id="🚀-preset-5-respectable-when-the-whip-comes-down-raw-punk-overdrive" tabindex="-1">🚀 Preset 5: &quot;Respectable&quot; &amp; &quot;When The Whip Comes Down&quot; (Raw Punk Overdrive) <a class="header-anchor" href="#🚀-preset-5-respectable-when-the-whip-comes-down-raw-punk-overdrive" aria-label="Permalink to &quot;🚀 Preset 5: &quot;Respectable&quot; &amp; &quot;When The Whip Comes Down&quot; (Raw Punk Overdrive)&quot;">​</a></h3><ul><li><strong>Channel Mode:</strong> <code>IN 1 (Crunch)</code></li><li><strong>Bright Switch:</strong> <code>ON</code></li><li><strong>Amp Tone Stack:</strong> Gain: <code>8.5</code> | Treble: <code>8.0</code> | Bass: <code>4.0</code> | Middle: <code>8.0</code> | Presence: <code>7.0</code> | Master: <code>7.5</code></li><li><strong>Cabinet:</strong> <code>4x12 Big</code></li></ul><h3 id="👑-preset-6-some-girls-solo-tattoo-you-leads-singing-tube-sustain" tabindex="-1">👑 Preset 6: &quot;Some Girls Solo / Tattoo You Leads&quot; (Singing Tube Sustain) <a class="header-anchor" href="#👑-preset-6-some-girls-solo-tattoo-you-leads-singing-tube-sustain" aria-label="Permalink to &quot;👑 Preset 6: &quot;Some Girls Solo / Tattoo You Leads&quot; (Singing Tube Sustain)&quot;">​</a></h3><ul><li><strong>Channel Mode:</strong> <code>IN 1 (Lead 10)</code></li><li><strong>Bright Switch:</strong> <code>ON</code></li><li><strong>Amp Tone Stack:</strong> Gain: <code>9.0</code> | Treble: <code>7.0</code> | Bass: <code>4.5</code> | Middle: <code>7.5</code> | Presence: <code>6.5</code> | Master: <code>7.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: +2dB</code> | <code>240Hz: -1.5dB</code> | <code>750Hz: +4dB</code> | <code>2.2kHz: +3dB</code> | <code>6.6kHz: +2dB</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>160 ms</code> | Repeats: <code>35%</code> | Mix: <code>28%</code></li><li><strong>Cabinet:</strong> <code>441 Center</code></li></ul><hr><h2 id="_5-standalone-audio-configuration" tabindex="-1">5. Standalone Audio Configuration <a class="header-anchor" href="#_5-standalone-audio-configuration" aria-label="Permalink to &quot;5. Standalone Audio Configuration&quot;">​</a></h2><p>When running Beast of Burden as a standalone application on Windows:</p><ol><li><strong>Audio Device Type:</strong> Select <strong>ASIO</strong> (essential for ultra-low latency).</li><li><strong>Device:</strong> Choose your audio interface&#39;s native ASIO driver (e.g., <em>Focusrite USB ASIO</em>, <em>Universal Audio Thunderbolt ASIO</em>).</li><li><strong>Sample Rate:</strong> Set to <strong>48000 Hz</strong> (48 kHz) for optimal neural inference.</li><li><strong>Buffer Size:</strong> Set to <strong>128 samples</strong> (2.7 ms) or <strong>256 samples</strong> (5.3 ms) for seamless real-time monitoring.</li></ol><hr><h2 id="_6-technical-specifications" tabindex="-1">6. Technical Specifications <a class="header-anchor" href="#_6-technical-specifications" aria-label="Permalink to &quot;6. Technical Specifications&quot;">​</a></h2><ul><li><strong>Formats:</strong> VST3 (64-bit) and Standalone Windows Executable (.exe).</li><li><strong>Sample Rates:</strong> 44.1 kHz, 48 kHz, 88.2 kHz, 96 kHz (Internal neural engine handles multi-rate inference).</li><li><strong>DSP Framework:</strong> JUCE 9 + Eigen + Neural Amp Modeler (NAM) C++ Core.</li><li><strong>Instruction Set:</strong> Full SIMD AVX/AVX2 Vectorization.</li><li><strong>Developer:</strong> Main St Audio Labs.</li></ul><hr>`,63)),o("div",c,[e[1]||(e[1]=o("div",{class:"rock-card-contact-title"},"Questions or Early Access Inquiries?",-1)),e[2]||(e[2]=o("p",{class:"rock-card-contact-desc"},"We love hearing from guitarists and mixing engineers. Send us your questions or suggestions.",-1)),o("div",l,[e[0]||(e[0]=o("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),o("button",{class:"rock-copy-btn",onClick:a},r(t.value),1)])])]))}});export{m as __pageData,b as default};
